H.background();
const a1 = P.a1, d = P.d, nMax = Math.max(2, Math.round(P.n));
const v = H.plot2d({ xMin: 0, xMax: nMax + 1, yMin: 0, yMax: Math.max(5, a1 + (nMax - 1) * d) * 1.15 });
v.grid(); v.axes();
const an = (n) => a1 + (n - 1) * d;
const shown = 1 + Math.floor((t * 0.9) % nMax);
let sum = 0;
for (let n = 1; n <= nMax; n++) {
  const h = Math.max(0, an(n));
  const lit = n <= shown;
  v.rect(n - 0.4, 0, 0.8, h, { fill: lit ? H.colors.accent : H.colors.panel, stroke: H.colors.accent, width: 1.5 });
  if (lit) sum += an(n);
}
const formula = nMax * (a1 + an(nMax)) / 2;
v.line(0.6, a1, nMax + 0.4, an(nMax), { color: H.colors.violet, width: 2, dash: [5, 5] });
v.circle(shown, Math.max(0, an(shown)) / 2, 6 + 2 * Math.sin(t * 4), { fill: H.colors.warn });
H.text("Arithmetic series:  S_n = n(a_1 + a_n)/2", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("adding " + shown + " terms:  running sum = " + sum.toFixed(1) + "    full S_" + nMax + " = " + formula.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "counted term", color: H.colors.accent }, { label: "not yet added", color: H.colors.panel }], H.W - 200, 28);
